package glitch

import data.glitch_lib

is_username_field(name) {
    regex.match("(?i)^(user|username|default_user|master_username|db_user|login_name|initial_user|bootstrap_user|admin_login|admin_user|ssh_user|master_user|db_master_user|superuser_login|run_as|run_as_user|admin_password|root_password)$", name)
}

is_privileged_identity(value) {
    regex.match("(?i)^(admin|administrator|root|superuser|sa|dba)$", value)
}

is_role_field(name) {
    regex.match("(?i)^(role|roles|administrator_role|root_role|account_type|account_role|user_role|owner_role)$", name)
}

is_admin_flag(name) {
    regex.match("(?i)^(is_admin|admin_enabled|admin_access|privileged|run_as_root|grant_all|full_access|attach_admin_policy|admin_group|billing_admin)$", name)
}

is_permission_field(name) {
    regex.match("(?i).*(action|policy|permission|privilege).*", name)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]

    is_username_field(attr.name)
    attr.value.ir_type == "String"
    is_privileged_identity(attr.value.value)

    result := {
        "type": "sec_def_admin",
        "element": attr,
        "path": parent.path,
        "description": "Admin by Default - A privileged username or identity is used by default, violating the Principle of Least Privilege. (CWE-1188)"
    }
}

